<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docker-guide</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wait</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --for=condition=complete</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> job/migrate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --timeout=180s</span></span>
